def vvt(base, bank, cam):
    what = "впускного" if cam == "A" else "выпускного"
    code(hexcode(base), "Клапан фазовращателя %s распредвала (банк %d): цепь" % (what, bank), "vvt_sol",
         m="Блок не видит нормального тока в цепи клапана фазовращателя: обрыв, разъём, обмотка.")
    code(hexcode(base + 1), "Фазы %s распредвала слишком ранние (банк %d)" % (what, bank), "vvt_perf",
         m="Фактический угол распредвала ушёл в опережение дальше команды: муфта не возвращается — масло, клапан или сама муфта.")
    code(hexcode(base + 2), "Фазы %s распредвала запаздывают (банк %d)" % (what, bank), "vvt_perf",
         m="Распредвал не доходит до заданного опережения: не хватает давления масла или залип клапан/муфта. На холодную и на старом масле — самый частый вариант.")

