def heater(base, bank, sensor, extra_res=None):
    n = "Подогрев лямбда-зонда (банк %d, датчик %d)" % (bank, sensor)
    code(hexcode(base), n + ": цепь управления", "lambda_heater", m="Блок не видит нормального тока в цепи нагревателя зонда.")
    code(hexcode(base + 1), n + ": низкий уровень", "lambda_heater", m="Цепь подогрева замкнута на массу или нагреватель имеет слишком низкое сопротивление.")
    code(hexcode(base + 2), n + ": высокий уровень", "lambda_heater", m="Цепь подогрева оборвана: перегоревшая спираль, предохранитель, разъём.")
    if extra_res:
        code(extra_res, n + ": сопротивление нагревателя вне нормы", "lambda_heater", m="Сопротивление нагревателя зонда не совпадает с ожидаемым — старение зонда или неоригинальный зонд.")

