def o2(base, bank, sensor, up):
    fam = "lambda1" if up else "lambda2"
    n = "Лямбда-зонд (банк %d, датчик %d)" % (bank, sensor)
    code(hexcode(base), n + ": цепь", fam, m="Сигнал зонда вне рабочего окна: обрыв, замыкание, разъём.")
    code(hexcode(base + 1), n + ": низкое напряжение (постоянно «бедно»)", fam,
         m="Зонд долго держит сигнал у 0,1 В. Либо смесь реально бедная (подсос), либо зонд состарился, либо сигнальный провод замкнут на массу.",
         causes=["подсос воздуха во впуске или в выпуске до зонда", "негерметичный выпуск", "зонд состарился", "замыкание сигнального провода на массу"] if up else None)
    code(hexcode(base + 2), n + ": высокое напряжение (постоянно «богато»)", fam,
         m="Зонд долго держит сигнал у 0,9 В: богатая смесь, замыкание сигнала на питание подогрева, отравленный зонд.",
         causes=["богатая смесь: форсунки, давление топлива, ДМРВ", "замыкание сигнального провода на плюс (например, на цепь подогрева внутри зонда)", "зонд отравлен присадками"] if up else None)
    code(hexcode(base + 3), n + ": медленный отклик", fam,
         m="Зонд переключается между «бедно» и «богато» медленнее нормы: состарился, загрязнён, или его «тормозит» подсос выпуска.")
    code(hexcode(base + 4), n + ": нет активности", fam,
         m="Сигнал зонда не меняется вообще: зонд холодный (подогрев), оборван, или разъём отсоединён.")
    code(hexcode(base + 5), n + ": подогрев неисправен", "lambda_heater", m="Нагреватель зонда не работает: спираль, предохранитель, разъём.")

