def cat(base, bank):
    code(hexcode(base), "Катализатор работает неэффективно (банк %d)" % bank, "catalyst",
         m="Второй лямбда-зонд повторяет колебания первого: катализатор не накапливает кислород.",
         r={"P0300": "пропуски заливают катализатор бензином", "P0171": "бедная горячая смесь", "P0172": "богатая смесь перегревает",
            "P0133": "ленивый первый зонд перегружает катализатор и даёт ложный код", "P0136": "второй зонд может врать сам",
            "P0141": "без подогрева второй зонд молчит"})
    code(hexcode(base + 1), "Катализатор прогрева работает неэффективно (банк %d)" % bank, "catalyst", m="Не справляется первый (ближний к мотору) катализатор.")
    code(hexcode(base + 2), "Основной катализатор работает неэффективно (банк %d)" % bank, "catalyst", m="Не справляется основной катализатор.")
    code(hexcode(base + 3), "Подогреваемый катализатор работает неэффективно (банк %d)" % bank, "catalyst", m="Катализатор с электроподогревом не выходит на эффективность.")
    code(hexcode(base + 4), "Подогреваемый катализатор: температура ниже порога (банк %d)" % bank, "catalyst", m="Катализатор не прогрелся.")
    n = "Датчик температуры катализатора (банк %d)" % bank
    code(hexcode(base + 5), n + ": цепь", "egt", m="Цепь датчика температуры катализатора.")
    code(hexcode(base + 6), n + ": вне диапазона", "egt", m="Температура катализатора не соответствует режиму.")
    code(hexcode(base + 7), n + ": низкий сигнал", "egt", m="Замыкание на массу.")
    code(hexcode(base + 8), n + ": высокий сигнал", "egt", m="Обрыв.")
