def sol(base, name, fam="trans_sol"):
    code(hexcode(base), name + ": цепь", fam, m="Обрыв или замыкание в цепи соленоида.")
    code(hexcode(base + 1), name + ": не отрабатывает / застрял выключенным", fam, m="Соленоид не даёт ожидаемого гидравлического отклика: залип, грязное масло, износ гидроблока.")
    code(hexcode(base + 2), name + ": застрял включённым", fam, m="Соленоид не закрывается: залип открытым.")
    code(hexcode(base + 3), name + ": электрическая", fam, m="Электрическая неисправность цепи соленоида.")
    code(hexcode(base + 4), name + ": прерывистая", fam, m="Цепь соленоида пропадает.")

